import{_ as i,o as l,c as r,ai as e}from"./chunks/framework.ampVZV4B.js";const _=JSON.parse('{"title":"对话式 AI 的高效用法","description":"","frontmatter":{},"headers":[],"relativePath":"ai/productivity/chat-workflow.md","filePath":"ai/productivity/chat-workflow.md"}'),t={name:"ai/productivity/chat-workflow.md"};function o(n,a,s,h,p,d){return l(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="对话式-ai-的高效用法" tabindex="-1">对话式 AI 的高效用法 <a class="header-anchor" href="#对话式-ai-的高效用法" aria-label="Permalink to “对话式 AI 的高效用法”">​</a></h1><h2 id="场景与问题" tabindex="-1">场景与问题 <a class="header-anchor" href="#场景与问题" aria-label="Permalink to “场景与问题”">​</a></h2><p>大多数人打开 ChatGPT 或 Claude 的第一句话是：“帮我写个方案”“这个报错怎么回事”。AI 也会回一大段，但往往不是你想要的：方向偏了、格式不对、关键信息靠猜。于是你觉得“AI 也就那样”，换个问题再问，还是不满意，最后自己动手写，时间已经浪费了二十分钟。</p><p>问题通常不在模型，在提问方式。作为写了 10 年代码的人，我发现这和接需求是一个道理：需求说不清，开发出来的东西一定不对。把 AI 当成一个聪明但完全不了解你背景的同事，你就知道该怎么开口了。</p><p>下面这套方法不需要任何技巧储备，核心就四件事：把信息一次给足、多轮往具体处收敛、两端加上对齐与验收、把验证过的结构存成模板。</p><h2 id="做法" tabindex="-1">做法 <a class="header-anchor" href="#做法" aria-label="Permalink to “做法”">​</a></h2><h3 id="_1-按「背景-目标-约束-输出格式」四段式提问" tabindex="-1">1. 按「背景-目标-约束-输出格式」四段式提问 <a class="header-anchor" href="#_1-按「背景-目标-约束-输出格式」四段式提问" aria-label="Permalink to “1. 按「背景-目标-约束-输出格式」四段式提问”">​</a></h3><ul><li><strong>背景</strong>：它是谁、在什么上下文里。例如“我在一个 Spring Boot 项目里，JDK 17，用 MyBatis-Plus，MySQL 8”。</li><li><strong>目标</strong>：你到底要什么。一句话说清，不要“帮我优化一下”这种模糊表述。</li><li><strong>约束</strong>：不能做什么、必须遵守什么。例如“不能引入新依赖”“保持现有接口签名不变”“QPS 不能低于现在的水平”。</li><li><strong>输出格式</strong>：你要代码、表格、清单还是 markdown？要不要分点？要不要给理由？</li></ul><p>四个要素齐了，AI 第一轮的命中率会明显提高。信息不全时，宁可多写几行，也别赌它猜对。</p><p>举个对比。同一件事两种问法：</p><blockquote><p>差：“这个接口好慢，帮我优化。”</p><p>好：“背景：Spring Boot 2.7 项目，/api/orders 接口在订单量 10 万时响应 3 秒（正常应 &lt;300ms），慢日志显示瓶颈在一条全表扫描的 SQL。目标：把这个接口优化到 300ms 以内。约束：不加新依赖，不改接口出入参，分页参数保留。输出：先给优化方案和理由，确认后我再让你改代码。”</p></blockquote><p>第二种问法，AI 第一轮给出的方案基本能用；第一种问法，它只能猜，猜错的成本由你承担。</p><h3 id="_2-多轮迭代-不要指望一轮到位" tabindex="-1">2. 多轮迭代，不要指望一轮到位 <a class="header-anchor" href="#_2-多轮迭代-不要指望一轮到位" aria-label="Permalink to “2. 多轮迭代，不要指望一轮到位”">​</a></h3><p>把第一轮回答当草稿。第二轮往具体处收敛：“约束 2 你没满足，第 3 个参数应该是可选的”“这个方案在并发下有问题，重新考虑竞态”。每轮只改一个维度，方向才不会乱。</p><p>一次性把十个要求全丢过去，AI 往往只满足其中六个，你还不知道漏了哪个。所以迭代的节奏是：</p><ul><li>第一轮：定方向，看整体思路对不对，错了立刻纠，不要在错的方向上修细节。</li><li>第二轮起：逐条落实约束，每轮聚焦一到两个点。</li><li>最后一轮：整体对照原始要求通读一遍，补齐遗漏。</li></ul><h3 id="_3-让-ai-复述与自检" tabindex="-1">3. 让 AI 复述与自检 <a class="header-anchor" href="#_3-让-ai-复述与自检" aria-label="Permalink to “3. 让 AI 复述与自检”">​</a></h3><p>在提问末尾加两句话，成本极低但收益极高：</p><ul><li>开头加：“先复述你对这个任务的理解，确认无误再开始。”</li><li>结尾加：“回答完后，对照检查上面的每一条约束，列出哪些满足、哪些没满足。”</li></ul><p>复述拦的是“开工前跑偏”，自检拦的是“干完漏项”。它的原理就是需求评审：先对齐，再干活；干完再验收。尤其是约束多的时候，让它自己列检查表，比你肉眼挑错快得多。</p><h3 id="_4-沉淀常用模板" tabindex="-1">4. 沉淀常用模板 <a class="header-anchor" href="#_4-沉淀常用模板" aria-label="Permalink to “4. 沉淀常用模板”">​</a></h3><p>把验证过的提问结构存下来，形成自己的模板库。几条高频的：</p><ul><li><strong>查报错</strong>：背景（版本、栈、复现步骤）+ 现象（完整报错栈）+ 已尝试 + 要求（给出根因，不要只猜表象）</li><li><strong>写代码</strong>：背景（项目结构、技术栈）+ 目标（函数级描述）+ 约束（风格、依赖、边界条件）+ 输出（可直接粘贴的完整代码）</li><li><strong>写文档</strong>：背景 + 读者是谁 + 篇幅与结构 + 语气要求</li><li><strong>做决策</strong>：背景 + 备选项 + 权衡维度 + 要求列出优劣并给出推荐理由</li></ul><p>模板不是死板，是省掉每次从零组织语言的成本。放在一个 markdown 文件里，用的时候复制出来改几个占位符即可。</p><h2 id="关键要点" tabindex="-1">关键要点 <a class="header-anchor" href="#关键要点" aria-label="Permalink to “关键要点”">​</a></h2><ul><li>提问四段式：背景、目标、约束、输出格式，缺什么就补什么，宁多勿少。</li><li>把 AI 当不了解背景的同事，先交代上下文再提要求。</li><li>第一轮当草稿定方向，之后每轮只改一个维度，逐步收敛。</li><li>开头让它复述理解，结尾让它对照约束自检，两端各设一道关。</li><li>好用的提问存成模板，下次直接套，别每次重新发明。</li><li>事实性内容仍需自己核对，模板解决的是表达效率，不是正确性。</li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>对话式 AI 的效率差距，八成来自提问结构。四段式把信息一次给足，多轮迭代往具体处收敛，复述与自检守住开工和交付两端，模板把验证过的结构复用下去。这套方法和做需求评审、写 ticket 是同一套思维，工程师上手几乎没有学习成本，但能让你从“问了白问”变成“第一轮就接近可用”。</p>',28)])])}const m=i(t,[["render",o]]);export{_ as __pageData,m as default};
